with flattened as (select id, service, log_ts, latency_ms, status_code, k, v from app_logs lateral view outer explode(context) li as k, v) select id, service, log_ts, latency_ms, status_code, k, v, corr(latency_ms, status_code) over (partition by service) as corr_latency_ms_status_code, max(latency_ms) over (partition by service order by cast(log_ts as bigint) asc range between 3600 preceding and current row) as latency_ms_max_1h from flattened;
